package ama.meeting;
import ama.contract.WorkspaceContracts.MeetingItem;import java.time.LocalDate;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Filters authorized bounded candidates. A page may be empty while its signed cursor advances. */
public record MeetingListFilter(String q,Set<String> stages,Set<String> categories,LocalDate from,LocalDate to,String topic) {
 public MeetingListFilter(String q,Set<String> stages,Set<String> categories,LocalDate from,LocalDate to){this(q,stages,categories,from,to,null);}
 public static final MeetingListFilter NONE=new MeetingListFilter("",Set.of(),Set.of(),null,null);
 public MeetingListFilter {q=Objects.requireNonNull(q).strip();stages=Collections.unmodifiableSet(new TreeSet<>(stages));categories=Collections.unmodifiableSet(new TreeSet<>(categories));if(q.codePointCount(0,q.length())>128||q.codePoints().anyMatch(Character::isISOControl)||stages.size()>8||!MeetingListScan.STAGES.containsAll(stages)||categories.size()>32||categories.stream().anyMatch(x->x.isBlank()||x.length()>64||x.contains(",")||x.codePoints().anyMatch(Character::isISOControl))||from!=null&&to!=null&&from.isAfter(to))throw new IllegalArgumentException("Invalid list filters");if(topic!=null&&!topic.equals("__none"))try{ama.contract.MinutesContracts.uuid(topic);}catch(ama.contract.MinutesContracts.Failure invalid){throw new IllegalArgumentException("Invalid topic filter");}}
 public String cursorKey(){try{String canonical=q.length()+":"+q+"|"+stages+"|"+categories+"|"+from+"|"+to;if(topic!=null)canonical+="|topic-v1:"+topic;return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public boolean matches(MeetingItem item){String needle=q.toLowerCase(Locale.ROOT);return(stages.isEmpty()||stages.contains(item.workspaceStage()))&&(categories.isEmpty()||item.category()!=null&&categories.contains(item.category()))&&(from==null||item.occurredOn()!=null&&!item.occurredOn().isBefore(from))&&(to==null||item.occurredOn()!=null&&!item.occurredOn().isAfter(to))&&(needle.isEmpty()||item.id().toLowerCase(Locale.ROOT).contains(needle)||item.name()!=null&&item.name().toLowerCase(Locale.ROOT).contains(needle)||item.participants().stream().anyMatch(x->x.toLowerCase(Locale.ROOT).contains(needle)));}
}
